parameters.message:
={{
(() => {
  const escapeHtml = (value) => String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

  const source = String($json.text ?? '')
    .replace(/\r\n?/g, '\n')
    .replace(/\\n/g, '\n');

  const healthMatch = source.match(
    /OVERALL PROJECT HEALTH:\s*\*{0,2}(Red|Amber|Green)\*{0,2}\s*\n?([\s\S]*)/i
  );

  const status = healthMatch
    ? healthMatch[1].toUpperCase()
    : 'UNKNOWN';

  const healthDescription = healthMatch
    ? healthMatch[2].trim()
    : 'No project health assessment provided.';

  const colors = {
    RED: {
      background: '#FDECEC',
      border: '#DC2626',
      text: '#B91C1C'
    },
    AMBER: {
      background: '#FFF7E6',
      border: '#D97706',
      text: '#92400E'
    },
    GREEN: {
      background: '#ECFDF5',
      border: '#16A34A',
      text: '#166534'
    },
    UNKNOWN: {
      background: '#F3F4F6',
      border: '#6B7280',
      text: '#374151'
    }
  };

  const c = colors[status];

  let report = healthMatch
    ? source.slice(0, healthMatch.index).trim()
    : source.trim();

  // Remove duplicate title and report date
  report = report
    .replace(/^WEEKLY TEAM PROGRESS REPORT\s*/i, '')
    .replace(/^Report Date:\s*[^\n]+\n?/i, '')
    .trim();

  // Escape HTML before adding formatting
  report = escapeHtml(report);

  // Convert Markdown bold
  report = report.replace(
    /\*\*(.*?)\*\*/g,
    '<strong>$1</strong>'
  );

  // Format report section headings
  report = report.replace(
    /^([A-Z][A-Z -]+):[ \t]*$/gm,
    '<strong style="display:block;color:#176B48;font-size:16px;margin-top:22px;margin-bottom:8px;">$1</strong>'
  );

  // Preserve line breaks only in report text
  report = report.replace(/\n/g, '<br>');

  // Format health description separately
  const formattedHealth = escapeHtml(healthDescription)
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/\n/g, '<br>');

  return `
<table role="presentation" cellpadding="0" cellspacing="0" border="0"
  style="width:100%;max-width:750px;font-family:Arial,sans-serif;color:#222222;">

  <tr>
    <td style="padding:20px;">

      <h2 style="color:#176B48;margin:0 0 10px 0;">
        FlowPilot | Weekly Team Progress Report
      </h2>

      <p style="color:#666666;font-size:14px;">
        <strong>Report Date:</strong> ${$now.toISODate()}
      </p>

      <hr style="border:0;border-top:1px solid #DDDDDD;margin:20px 0;">

      <div style="font-size:14px;line-height:1.8;">
        ${report}
      </div>

      <table role="presentation" cellpadding="0" cellspacing="0" border="0"
        style="width:100%;margin-top:28px;border-collapse:collapse;">

        <tr>
          <td bgcolor="${c.background}"
            style="background-color:${c.background};border-left:6px solid ${c.border};padding:20px;">

            <div style="font-size:15px;font-weight:bold;color:${c.text};">
              OVERALL PROJECT HEALTH
            </div>

            <div style="font-size:24px;font-weight:bold;color:${c.text};padding-top:12px;padding-bottom:12px;">
              ${status}
            </div>

            <div style="font-size:14px;line-height:1.7;color:#333333;">
              ${formattedHealth}
            </div>

          </td>
        </tr>

      </table>

      <hr style="border:0;border-top:1px solid #DDDDDD;margin-top:28px;">

      <p style="font-size:12px;color:#777777;line-height:1.6;">
        This report was automatically generated by FlowPilot using AI.
        Review important decisions against the source task data.
      </p>

    </td>
  </tr>

</table>`;
})()
}}
